from collections import deque


def topological_sort(vertices, edges):
    """Topological sort using Kahn's algorithm.

    Args:
        vertices: iterable of vertex labels
        edges: iterable of (u, v) directed edges meaning u -> v

    Returns:
        list of vertices in topological order

    Raises:
        ValueError: if the graph contains a cycle
    """
    adj = {v: [] for v in vertices}
    in_degree = {v: 0 for v in vertices}

    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    queue = deque(v for v in vertices if in_degree[v] == 0)
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(vertices):
        raise ValueError("graph contains a cycle")

    return result


# ── Tests ──────────────────────────────────────────────────────────────

import unittest


class TestTopologicalSort(unittest.TestCase):
    def test_simple_chain(self):
        result = topological_sort([1, 2, 3], [(1, 2), (2, 3)])
        self.assertEqual(result, [1, 2, 3])

    def test_diamond(self):
        # 1 -> 2, 1 -> 3, 2 -> 4, 3 -> 4
        result = topological_sort([1, 2, 3, 4], [(1, 2), (1, 3), (2, 4), (3, 4)])
        self.assertEqual(result[0], 1)
        self.assertEqual(result[-1], 4)
        self.assertIn(result.index(2) < result.index(4), [True])
        self.assertIn(result.index(3) < result.index(4), [True])

    def test_single_vertex(self):
        self.assertEqual(topological_sort([1], []), [1])

    def test_disconnected_vertices(self):
        result = topological_sort([1, 2, 3], [])
        self.assertEqual(sorted(result), [1, 2, 3])

    def test_multiple_valid_orders(self):
        # 1 -> 2, 1 -> 3  — both [1,2,3] and [1,3,2] are valid
        result = topological_sort([1, 2, 3], [(1, 2), (1, 3)])
        self.assertEqual(result[0], 1)
        self.assertEqual(set(result[1:]), {2, 3})

    def test_cycle_raises(self):
        with self.assertRaises(ValueError):
            topological_sort([1, 2, 3], [(1, 2), (2, 3), (3, 1)])

    def test_self_loop_raises(self):
        with self.assertRaises(ValueError):
            topological_sort([1, 2], [(1, 1)])

    def test_larger_graph(self):
        edges = [(5, 2), (5, 0), (4, 0), (4, 1), (2, 3), (3, 1)]
        result = topological_sort([0, 1, 2, 3, 4, 5], edges)
        pos = {v: i for i, v in enumerate(result)}
        for u, v in edges:
            self.assertLess(pos[u], pos[v], f"{u} should come before {v}")

    def test_string_vertices(self):
        result = topological_sort(
            ["a", "b", "c"], [("a", "b"), ("b", "c")]
        )
        self.assertEqual(result, ["a", "b", "c"])


if __name__ == "__main__":
    unittest.main()
